// Builds the sticker catalog from the PNG files that are really in public/stickers, for BOTH sides of the app:
//   api/_stickers.js              the server's trusted list (a sticker is sent by id and checked against this)
//   src/utils/stickerCatalog.ts   the app's copy, used to draw the picker and the message
// Run: npm run stickers   (a test fails if either generated file is out of date or lists a pack that is not approved)
//
// ONLY the regular packs are listed here. "After Dark" (18+) is deliberately NOT in this file or anywhere in the build: it stays
// disabled until the requirements in docs/stickers.md are met. Adding its folder to public/stickers does nothing on its own.
import { readdirSync, writeFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

export const PACKS = [
  { id: 'sapphic-feelings', name: 'Sapphic Feelings' },
  { id: 'androgynous-sapphic', name: 'Androgynous Sapphic' },
];

const labelOf = (file) => file.replace(/\.png$/i, '').replace(/^\d+_/, '').replace(/_/g, ' ');

export function buildCatalog() {
  return PACKS.flatMap((pack) => {
    const dir = path.join(root, 'public', 'stickers', pack.id);
    if (!existsSync(dir)) throw new Error(`Missing sticker folder: public/stickers/${pack.id}`);
    return readdirSync(dir)
      .filter((f) => /\.png$/i.test(f))
      .sort()
      .map((filename, index) => {
        const num = filename.match(/^(\d{2})_/)?.[1];
        if (!num) throw new Error(`Sticker file must start with two digits and an underscore: ${pack.id}/${filename}`);
        return { id: `${pack.id}-${num}`, packId: pack.id, file: filename, label: labelOf(filename), order: index + 1 };
      });
  });
}

const header = '// AUTO-GENERATED by scripts/generate-stickers.mjs (npm run stickers). Do not edit by hand.\n';

export function render() {
  const stickers = buildCatalog();
  const ids = new Set(stickers.map((s) => s.id));
  if (ids.size !== stickers.length) throw new Error('Duplicate sticker ids');
  const rows = stickers.map((s) => `  ${JSON.stringify(s)},`).join('\n');
  const packs = PACKS.map((p) => `  ${JSON.stringify(p)},`).join('\n');
  return {
    server:
      header +
      `// The trusted sticker list. A sticker is sent by its id alone and checked against this; nothing else the app says about it is stored.\n` +
      `export const STICKER_PACKS = [\n${packs}\n];\n\nexport const STICKERS = [\n${rows}\n];\n`,
    client:
      header +
      `export type StickerPack = { id: string; name: string };\nexport type StickerEntry = { id: string; packId: string; file: string; label: string; order: number };\n\n` +
      `export const STICKER_PACKS: StickerPack[] = [\n${packs}\n];\n\nexport const STICKERS: StickerEntry[] = [\n${rows}\n];\n`,
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const { server, client } = render();
  writeFileSync(path.join(root, 'api', '_stickers.generated.js'), server);
  writeFileSync(path.join(root, 'src', 'utils', 'stickerCatalog.ts'), client);
  console.log(`stickers: ${buildCatalog().length} (${PACKS.map((p) => `${p.id}=${buildCatalog().filter((s) => s.packId === p.id).length}`).join(', ')})`);
}
